/**
 * RCABenchFactory interactive site.
 *
 * Zero dependencies, zero build step: the page reads `window.RBF_DATA`, which is
 * generated by `scripts/gen-examples.mjs` from the real exporters and the real
 * scorer. Every code sample shown here is a byte-exact artefact of that run.
 */
(function () {
  'use strict';

  var DATA = window.RBF_DATA;
  var FORMATS = DATA.formats;
  var TARGETS = DATA.targets;

  /** Which export target(s) back each documented format. */
  var FORMAT_TARGETS = {
    'openrca-1.0': ['openrca-1.0'],
    'openrca-2.0': ['openrca-2.0'],
    rcaeval: ['rcaeval-re1', 'rcaeval-re2', 'rcaeval-re3'],
    rca100: ['rca100'],
    aiops2025: ['aiops2025'],
    'cloud-opsbench': ['cloud-opsbench'],
    itbench: ['itbench'],
  };

  var SUITE_LABEL = {
    'rcaeval-re1': 'RE1 · metrics only',
    'rcaeval-re2': 'RE2 · multi-source',
    'rcaeval-re3': 'RE3 · code-level',
  };

  // ── tiny DOM helpers ────────────────────────────────────────────────
  function el(tag, props, children) {
    var node = document.createElement(tag);
    props = props || {};
    Object.keys(props).forEach(function (key) {
      var value = props[key];
      if (value === null || value === undefined || value === false) return;
      if (key === 'class') node.className = value;
      else if (key === 'text') node.textContent = value;
      else if (key === 'html') node.innerHTML = value;
      else if (key.slice(0, 2) === 'on') node.addEventListener(key.slice(2).toLowerCase(), value);
      else node.setAttribute(key, value);
    });
    (children || []).forEach(function (child) {
      if (child === null || child === undefined || child === false) return;
      node.appendChild(typeof child === 'string' ? document.createTextNode(child) : child);
    });
    return node;
  }

  function codeBlock(label, text, lang) {
    var pre = el('pre', { class: 'code' }, [el('code', { text: text })]);
    var copy = el('button', {
      class: 'copy',
      text: 'copy',
      onclick: function () {
        navigator.clipboard.writeText(text).then(
          function () {
            copy.textContent = 'copied';
            setTimeout(function () {
              copy.textContent = 'copy';
            }, 1200);
          },
          function () {
            copy.textContent = 'failed';
          },
        );
      },
    });
    var head = el('div', { class: 'code-head' }, [el('span', { text: label || '' }), el('span', { class: 'spacer' }), copy]);
    if (lang) pre.setAttribute('data-lang', lang);
    return el('div', { style: 'margin-bottom:14px' }, [head, pre]);
  }

  function sectionTitle(title, sub) {
    return el('div', {}, [el('h2', { class: 'title', text: title }), sub ? el('p', { class: 'sub', text: sub }) : null]);
  }

  // ── path matching between documented patterns and real exports ──────
  function patternToRegExp(pattern) {
    var escaped = pattern.replace(/[.+^${}()|[\]\\]/g, '\\$&');
    // `{caseId}` style placeholders match any path segment content.
    var withPlaceholders = escaped.replace(/\\\{[^}]*\\\}/g, '[^/]+');
    return new RegExp('^' + withPlaceholders + '$');
  }

  function documentedFile(spec, actualPath) {
    for (var i = 0; i < spec.files.length; i++) {
      if (patternToRegExp(spec.files[i].path).test(actualPath)) return spec.files[i];
    }
    // Fall back to suffix matching for scaffold paths with a case directory.
    for (var j = 0; j < spec.files.length; j++) {
      var tail = spec.files[j].path.split('/').pop();
      if (actualPath.split('/').pop() === tail) return spec.files[j];
    }
    return null;
  }

  function langFor(path) {
    if (path.endsWith('.json') || path.endsWith('.jsonl')) return 'json';
    if (path.endsWith('.csv')) return 'csv';
    if (path.endsWith('.txt')) return 'text';
    return 'text';
  }

  // ── overview ────────────────────────────────────────────────────────
  var LAYERS = [
    {
      id: 'L1',
      name: 'TelemetrySignal',
      one: 'one observed fact',
      body: 'metric · log · trace · event · alert · profile. Canonical UTC timestamp, OTel-semconv resource subset, and per-field provenance (direct / derived / inferred / defaulted).',
      fields: 'irVersion, resource{service.name, k8s.pod.name, …}, timestamp, rawOffsetMinutes, signal, payload, provenance',
    },
    {
      id: 'L2',
      name: 'EntityGraph',
      one: 'the topology every reference resolves against',
      body: 'entities (service / pod / node / container / db / mq / host / cluster / external) with aliases for the APM, Kubernetes and CMDB names of the same thing; edges typed contains | hosts | calls | same_as.',
      fields: 'entities[{entityId, kind, name, namespace, aliases[], attributes}], edges[{from, to, relation}]',
    },
    {
      id: 'L3',
      name: 'FaultCase',
      one: 'one failure plus its ground truth',
      body: 'fault type + category, injection time, window, and the ground truth: root-cause entity, causal chain (CausalStep[]) and ⟨comparator, value, unit⟩ evidence checkpoints.',
      fields: 'caseId, system, injectTime, window, fault{type, category, parameters}, groundTruth{rootCauseEntityId, causalChain[], evidenceCheckpoints[]}, query, difficulty',
    },
    {
      id: 'L4',
      name: 'QualityGateReport',
      one: 'the evidence that the case is usable',
      body: 'G1 structural → G2 semantic → G3 validity → G4 solvability → G5 anti-pollution, plus the mutation-suite verdict that proves the gates themselves still catch corruption.',
      fields: 'caseId, gateRunId, results[{gateId, status, violations[]}], finalStatus admitted | quarantined | rejected, mutationTestPassed',
    },
  ];

  function renderOverview() {
    var view = document.getElementById('view');
    view.innerHTML = '';

    var hero = el('section', { class: 'hero' }, [
      el('span', { class: 'badge ok', text: 'open source · Apache-2.0' }),
      el('h1', { text: 'Turn enterprise telemetry into authoritative RCA benchmark field contracts' }),
      el('p', {
        class: 'lede',
        text:
          'RCABenchFactory ingests whatever your platform actually emits - flat files, OTLP, ' +
          'vendor exports - normalises it into one intermediate representation, proves it is usable ' +
          'with five quality gates, and exports it to seven authoritative RCA benchmark contracts.',
      }),
      el('div', { class: 'cta-row' }, [
        el('a', { class: 'btn primary', href: '#/tutorial', text: 'Start the tutorial' }),
        el('a', { class: 'btn', href: '#/formats', text: 'Explore the 7 formats' }),
        el('a', { class: 'btn', href: 'https://github.com/AgentiX-E/rca-bench-factory', text: 'View on GitHub' }),
      ]),
      el('div', { class: 'stats' }, [
        stat('7', 'target benchmark contracts'),
        stat('6', 'observability modalities'),
        stat('5', 'quality gates (G1–G5)'),
        stat('15', 'gate mutation tests'),
        stat('100%', 'reference integrity enforced'),
      ]),
    ]);
    view.appendChild(hero);

    // Problem / solution
    var problem = el('section', { class: 'block' }, [
      sectionTitle('The gap this closes', 'Enterprise telemetry is not a benchmark. Benchmarks demand a field contract.'),
      el('div', { class: 'grid cols-3' }, [
        card('Dialects', 'The same CPU saturation is a ratio in one export, a percentage in another, and offset-less local time in a third.'),
        card('Missing structure', 'No topology, no event modality, no answer key isolation - so the emitted set silently violates the target contract.'),
        card('Unproven labels', 'A ground truth nobody can verify is a benchmark nobody can trust. Guessing is not an option.'),
      ]),
      el('div', { class: 'grid cols-3', style: 'margin-top:14px' }, [
        card('One IR, four layers', 'Signals, entity graph, fault cases and gate reports - every reference must resolve, every inferred field is marked as such.'),
        card('Gates before export', 'G1–G5 admit, quarantine or reject a case with a violation code. The gates themselves are mutation-tested (MT-01 … MT-15).'),
        card('Verified, not asserted', 'Score = structural pass rate + Golden-Master checksum match. Exit code 1 on failure, so CI can gate on it.'),
      ]),
    ]);
    view.appendChild(problem);

    // IR layers
    var layers = el('section', { class: 'block' }, [
      sectionTitle('The intermediate representation', 'Four layers. Two invariants: every entity reference resolves, and nothing inferred is used as a ground-truth key.'),
    ]);
    LAYERS.forEach(function (layer) {
      layers.appendChild(
        el('div', { class: 'card', style: 'margin-bottom:10px' }, [
          el('div', { class: 'layer' }, [
            el('div', { class: 'idx' }, [el('b', { text: layer.id }), el('div', { class: 'small', text: 'layer' })]),
            el('div', {}, [
              el('h4', { text: layer.name + ' — ' + layer.one }),
              el('p', { text: layer.body }),
              codeBlock('fields', layer.fields, 'text'),
            ]),
          ]),
        ]),
      );
    });
    view.appendChild(layers);

    // Coverage matrix
    view.appendChild(
      el('section', { class: 'block' }, [
        sectionTitle('Which benchmark can see what', 'One ground truth, projected seven ways. Pick the contract that matches the question you are asking.'),
        matrixTable(),
        el('p', { class: 'small', style: 'margin-top:10px', text: '● = the benchmark consumes that modality. M metric · L log · T trace · E event · A alert · Topo topology · Conf config/state · CD change/deploy.' }),
      ]),
    );
  }

  function stat(value, label) {
    return el('div', { class: 'stat' }, [el('b', { text: value }), el('span', { text: label })]);
  }

  function card(title, body) {
    return el('div', { class: 'card' }, [el('h4', { text: title }), el('p', { text: body })]);
  }

  function matrixTable() {
    var cols = ['M', 'L', 'T', 'E', 'A', 'Topo', 'Conf', 'CD'];
    var rows = [
      ['OpenRCA 1.0', ['M', 'L', 'T']],
      ['OpenRCA 2.0 (PAVE)', ['M', 'L', 'T']],
      ['RCAEval RE1 / RE2 / RE3', ['M', 'L', 'T']],
      ['RCA100 / AgenticOpsEval', ['M', 'L', 'T', 'E', 'A', 'Topo']],
      ['AIOps2025', ['M', 'L', 'T', 'E', 'A']],
      ['Cloud-OpsBench', ['M', 'L', 'T', 'Conf']],
      ['ITBench (SRE)', ['M', 'L', 'T', 'E', 'CD']],
    ];
    var head = el('tr', {}, [el('th', { text: 'Benchmark' })].concat(
      cols.map(function (c) {
        return el('th', { text: c, style: 'text-align:center' });
      }),
    ));
    var body = rows.map(function (row) {
      return el('tr', {}, [el('td', { text: row[0] })].concat(
        cols.map(function (c) {
          var on = row[1].indexOf(c) >= 0;
          return el('td', { text: on ? '●' : '·', style: 'text-align:center;color:' + (on ? 'var(--accent-2)' : 'var(--fg-faint)') });
        }),
      ));
    });
    return el('div', { class: 'table-wrap' }, [el('table', {}, [el('thead', {}, [head]), el('tbody', {}, body)])]);
  }

  // ── formats explorer ────────────────────────────────────────────────
  var state = { format: FORMATS[0].id, target: null, file: null };

  function renderFormats() {
    var view = document.getElementById('view');
    view.innerHTML = '';

    view.appendChild(
      sectionTitle(
        'Format explorer',
        'Every field of every file, with the example produced by the real exporter. Click a file, search the fields, copy the command.',
      ),
    );

    var tabs = el('div', { class: 'tabs' });
    FORMATS.forEach(function (spec) {
      tabs.appendChild(
        el('button', {
          class: 'tab' + (spec.id === state.format ? ' active' : ''),
          text: spec.name,
          onclick: function () {
            state.format = spec.id;
            state.file = null;
            renderFormats();
          },
        }),
      );
    });
    view.appendChild(tabs);

    var spec = FORMATS.filter(function (f) {
      return f.id === state.format;
    })[0];
    var targetIds = FORMAT_TARGETS[spec.id];
    if (state.target === null || targetIds.indexOf(state.target) < 0) state.target = targetIds[0];

    view.appendChild(
      el('div', { class: 'card', style: 'margin-bottom:16px' }, [
        el('div', { style: 'display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:8px' }, [
          el('h4', { style: 'margin:0', text: spec.name }),
          el('span', { class: 'badge', text: spec.vendor }),
          el('span', { class: 'badge', text: spec.venue }),
          el('span', { class: 'badge ok', text: 'contract ' + spec.contractVersion }),
        ].concat(
          spec.modalities.map(function (m) {
            return el('span', { class: 'chip', text: m });
          }),
        )),
        el('p', { text: spec.summary }),
        el('dl', { class: 'kv', style: 'margin-top:12px' }, [
          el('dt', { text: 'emitter' }),
          el('dd', { class: 'mono', text: spec.emitter }),
          el('dt', { text: 'timezone' }),
          el('dd', { text: spec.timezone }),
          el('dt', { text: 'scoring' }),
          el('dd', { text: spec.scoringNote }),
        ]),
      ]),
    );

    if (targetIds.length > 1) {
      var suiteTabs = el('div', { class: 'tabs' });
      targetIds.forEach(function (id) {
        suiteTabs.appendChild(
          el('button', {
            class: 'tab' + (id === state.target ? ' active' : ''),
            text: SUITE_LABEL[id] || id,
            onclick: function () {
              state.target = id;
              state.file = null;
              renderFormats();
            },
          }),
        );
      });
      view.appendChild(suiteTabs);
    }

    var target = TARGETS[state.target];
    var paths = Object.keys(target.files);
    if (state.file === null || paths.indexOf(state.file) < 0) state.file = paths[0];

    if (paths.length === 0) {
      view.appendChild(
        el('div', { class: 'card', style: 'margin-bottom:16px;border-color:var(--warn)' }, [
          el('h4', { style: 'margin:0 0 6px', text: 'Nothing exported for ' + state.target + ' — by design' }),
          el('p', {
            text:
              'Every case was skipped, so no file was written. A skipped case never leaves ' +
              'artefacts behind. Reasons reported by the exporter:',
          }),
          el('ul', { class: 'tight' }, target.skipped.map(function (s) {
            return el('li', { class: 'mono', text: s.caseId + ' — ' + s.reason });
          })),
        ]),
      );
      view.appendChild(
        el('section', { class: 'block' }, [
          el('h3', { text: 'Commands' }),
          codeBlock(
            'export',
            'rca-bench export --target ' +
              (spec.id === 'rcaeval' ? 'rcaeval --suite ' + state.target.split('-')[1].toUpperCase() : spec.id) +
              ' --input examples/order-prod/bundle.json --out-dir ./out',
            'bash',
          ),
          el('h3', { text: 'Boundaries' }),
          el('ul', { class: 'tight' }, spec.boundaries.map(function (b) {
            return el('li', { text: b });
          })),
        ]),
      );
      return;
    }

    var tree = el('div', { class: 'filetree' }, [
      el('div', { class: 'head', text: paths.length + ' file(s) exported' }),
    ]);
    paths.forEach(function (path) {
      tree.appendChild(
        el('button', {
          class: path === state.file ? 'active' : '',
          text: path,
          onclick: function () {
            state.file = path;
            renderFormats();
          },
        }),
      );
    });

    var doc = documentedFile(spec, state.file);
    var panel = el('div', { class: 'panel' }, [
      el('h4', { class: 'mono', text: state.file }),
      el('p', { class: 'purpose', text: doc ? doc.purpose : 'Exported artefact.' }),
    ]);

    if (doc) {
      panel.appendChild(el('div', { class: 'small', style: 'margin-bottom:6px', text: 'emitted by ' + doc.emitter }));
      panel.appendChild(codeBlock('example · ' + langFor(state.file), target.files[state.file], langFor(state.file)));
      panel.appendChild(el('h3', { text: 'Fields' }));
      var search = el('input', { class: 'search', placeholder: 'filter fields, types or IR sources…', type: 'search' });
      var tbody = el('tbody');
      doc.fields.forEach(function (f) {
        tbody.appendChild(
          el('tr', { class: 'field-row', 'data-haystack': (f.name + ' ' + f.type + ' ' + f.source + ' ' + f.notes).toLowerCase() }, [
            el('td', { class: 'field', text: f.name }),
            el('td', { text: f.type }),
            el('td', { text: f.required ? 'yes' : 'no' }),
            el('td', { class: 'src', text: f.source }),
            el('td', { text: f.notes }),
          ]),
        );
      });
      search.addEventListener('input', function () {
        var needle = search.value.trim().toLowerCase();
        Array.prototype.forEach.call(tbody.querySelectorAll('.field-row'), function (row) {
          var hit = needle === '' || row.getAttribute('data-haystack').indexOf(needle) >= 0;
          row.classList.toggle('filtered', !hit);
        });
      });
      panel.appendChild(search);
      panel.appendChild(
        el('div', { class: 'table-wrap' }, [
          el('table', {}, [
            el('thead', {}, [
              el('tr', {}, [
                el('th', { text: 'Field' }),
                el('th', { text: 'Type' }),
                el('th', { text: 'Required' }),
                el('th', { text: 'Source (IR)' }),
                el('th', { text: 'Notes' }),
              ]),
            ]),
            tbody,
          ]),
        ]),
      );
    }

    view.appendChild(el('div', { class: 'explorer' }, [tree, panel]));

    var cmd =
      'rca-bench export --target ' +
      (spec.id === 'rcaeval' ? 'rcaeval --suite ' + state.target.split('-')[1].toUpperCase() : spec.id) +
      ' --input examples/order-prod/bundle.json --out-dir ./out';
    view.appendChild(
      el('section', { class: 'block' }, [
        el('h3', { text: 'Commands' }),
        codeBlock('export', cmd, 'bash'),
        codeBlock('score', 'rca-bench score --target ' + state.target + ' --dir ./out', 'bash'),
        el('h3', { text: 'Structural checks for ' + state.target }),
        el('ul', { class: 'checklist' }, target.report.structure.checks.map(function (c) {
          return el('li', {}, [
            el('span', { class: 'check-dot ' + (c.passed ? 'pass' : 'fail'), text: c.passed ? '✓' : '✗' }),
            el('span', { class: 'mono', text: c.id, style: 'min-width:190px' }),
            el('span', { text: c.detail, style: 'color:var(--fg-dim)' }),
          ]);
        })),
        el('p', { class: 'small', text: 'score ' + target.report.score + '/100 · passed=' + target.report.passed }),
        el('h3', { text: 'Boundaries' }),
        el('ul', { class: 'tight' }, spec.boundaries.map(function (b) {
          return el('li', { text: b });
        })),
      ]),
    );
  }

  // ── gates ───────────────────────────────────────────────────────────
  var GATES = [
    {
      id: 'G1',
      name: 'Structural',
      checks: 'The target\'s required signal kinds are present; a natural-language query exists when the contract needs one.',
      codes: 'MISSING_SIGNAL_KIND, MISSING_QUERY, MISSING_SERVICE_NAME',
    },
    {
      id: 'G2',
      name: 'Semantic',
      checks: 'Every entity reference resolves against the graph, and every causal hop exists in the topology (BFS over calls/hosts/contains).',
      codes: 'UNRESOLVED_SERVICE_NAME, CAUSAL_HOP_NOT_IN_TOPOLOGY',
    },
    {
      id: 'G3',
      name: 'Validity',
      checks: 'The anomaly is statistically real: the deviation from the baseline window reaches Z ≥ 2.0.',
      codes: 'ANOMALY_NOT_SIGNIFICANT',
    },
    {
      id: 'G4',
      name: 'Solvability',
      checks: 'Baseline locators must rank the true root cause inside top-K - a case nobody can solve is not a benchmark.',
      codes: 'UNSOLVABLE_CASE',
    },
    {
      id: 'G5',
      name: 'Anti-pollution',
      checks: 'The task text must not leak the answer key; "find the root cause" is fine, quoting the component is not.',
      codes: 'ANSWER_KEY_LEAK',
    },
  ];

  var DEMO_GATES = { G1: 'passed', G2: 'passed', G3: 'passed', G4: 'failed', G5: 'passed' };

  function renderGates() {
    var view = document.getElementById('view');
    view.innerHTML = '';
    view.appendChild(
      sectionTitle(
        'Quality gates',
        'A case is admitted only when all five gates pass. The demo bundle is deliberately tiny, so G4 quarantines it - which is exactly the point: quarantine is visible, silent repair is not.',
      ),
    );

    var grid = el('div', { class: 'grid cols-2' });
    GATES.forEach(function (gate) {
      var status = DEMO_GATES[gate.id];
      var badgeClass = status === 'passed' ? 'ok' : 'bad';
      grid.appendChild(
        el('div', { class: 'card' }, [
          el('div', { style: 'display:flex;gap:10px;align-items:center;margin-bottom:6px' }, [
            el('h4', { style: 'margin:0', text: gate.id + ' · ' + gate.name }),
            el('span', { class: 'badge ' + badgeClass, text: 'demo: ' + status }),
          ]),
          el('p', { text: gate.checks }),
          el('div', { class: 'small', style: 'margin-top:8px', text: 'violation codes: ' + gate.codes }),
        ]),
      );
    });
    view.appendChild(grid);

    view.appendChild(
      el('section', { class: 'block' }, [
        el('h3', { text: 'The mutation suite' }),
        el('p', {
          class: 'sub',
          text:
            'MT-01 … MT-15 corrupt a known-good case (drop the root cause, invert the timestamp, ' +
            'rename an entity, leak the answer key, …) and assert the gates intercept 100% of them. ' +
            'A mutation that slips through is a bug in the gates, not in the data - and it blocks ' +
            'the release until the gate is fixed.',
        }),
        codeBlock(
          'gate report for examples/order-prod/bundle.json --target rca100',
          JSON.stringify(
            {
              caseId: 'bundle',
              gateRunId: 'demo-1',
              results: Object.keys(DEMO_GATES).map(function (id) {
                return { gateId: id, status: DEMO_GATES[id] };
              }),
              finalStatus: 'quarantined',
            },
            null,
            2,
          ),
          'json',
        ),
        el('p', { class: 'small', text: 'admitted = all gates pass · quarantined = usable after human review (H5) · rejected = never admitted.' }),
      ]),
    );
  }

  // ── tutorial ────────────────────────────────────────────────────────
  var TUTORIAL = [
    {
      title: 'Ingest a flat file',
      why: 'Column names are auto-detected (ts → timestamp, svc → service, kpi_name → metric name). The offset flag is mandatory because the source carries no UTC offset - without it the row is quarantined, never guessed.',
      cmd:
        'node packages/cli/dist/main.js source \\\n' +
        '  --path examples/order-prod/metrics.csv \\\n' +
        '  --signal-kind metric \\\n' +
        '  --assume-offset-minutes 480',
      out:
        '{\n' +
        '  "irVersion": "2.0",\n' +
        '  "resource": { "service.name": "order-pod-1" },\n' +
        '  "timestamp": "2026-09-06T00:00:00.000Z",\n' +
        '  "rawOffsetMinutes": 480,\n' +
        '  "signal": "metric",\n' +
        '  "payload": { "kind": "metric", "name": "cpu_usage", "value": 0.2 }\n' +
        '}',
    },
    {
      title: 'Transform: timestamps, aliases, units',
      why: 'Three rules turn an unusable export into IR-ready values: normalise the offset-less timestamp, map the CMDB name to the APM service, convert the ratio 0.2 to the percentage 20 through a dimension-checked unit conversion.',
      cmd:
        'node packages/cli/dist/main.js transform \\\n' +
        '  --input examples/order-prod/records.json \\\n' +
        '  --rules examples/order-prod/rules.json',
      out:
        '"ts_utc": "2026-09-06T00:00:00.000Z",\n' +
        '"ts_offset_minutes": 480,\n' +
        '"service_name": "order",\n' +
        '"value_pct": 20,\n' +
        '"provenance": {\n' +
        '  "service_name": { "source": "derived", "ruleId": "t-cmdb-alias" },\n' +
        '  "value_pct": { "source": "derived", "ruleId": "t-ratio-to-percent" }\n' +
        '}',
    },
    {
      title: 'Assemble the bundle',
      why: 'The draft carries a bare fault type. The assembler normalises it and infers the category (cpu → resource), then schema-checks the whole bundle.',
      cmd: 'node packages/cli/dist/main.js case --input examples/order-prod/draft.json --output ./bundle.json',
      out: 'fault: { "type": "cpu", "category": "resource", "injectionMethod": "chaos-mesh" }',
    },
    {
      title: 'Run the gates',
      why: 'G1–G3 and G5 pass; G4 fails because two entities and one metric cannot demonstrate top-K solvability. The case is quarantined for review, not silently exported as if it were fine.',
      cmd: 'node packages/cli/dist/main.js gate --input examples/order-prod/bundle.json --target rca100',
      out:
        '{ "gateId": "G4", "status": "failed", "violations": [\n' +
        '  { "code": "UNSOLVABLE_CASE",\n' +
        '    "message": "only 0 baseline(s) locate the root cause within top-K" } ] }\n' +
        'finalStatus: quarantined',
    },
    {
      title: 'Export to a contract',
      why: 'Nine target ids: openrca-1.0, openrca-2.0, rcaeval (RE1/RE2/RE3), rca100, aiops2025, cloud-opsbench, itbench. A case that cannot satisfy the contract is reported in skipped with a reason.',
      cmd:
        'node packages/cli/dist/main.js export --target rca100 \\\n' +
        '  --input examples/order-prod/bundle.json --out-dir ./out',
      out:
        'cases/case-001/metrics.json\n' +
        'cases/case-001/logs.json\n' +
        'cases/case-001/traces.json\n' +
        'cases/case-001/events.json\n' +
        'cases/case-001/alerts.json\n' +
        'cases/case-001/task.json\n' +
        'cases/case-001/topology.json\n' +
        'answer_key/case-001.gt.json',
    },
    {
      title: 'Score the export',
      why: 'Without anchors the score is the structural pass rate; with anchors it is the mean of that and the Golden-Master checksum match rate. Exit code 1 on failure, so CI can gate on it.',
      cmd: 'node packages/cli/dist/main.js score --target rca100 --dir ./out',
      out:
        '{ "target": "rca100", "passed": true, "score": 100,\n' +
        '  "structure": { "checks": [\n' +
        '    { "id": "entity-refs-resolve", "passed": true,\n' +
        '      "detail": "every entity_id resolves into the topology" },\n' +
        '    { "id": "gt-structure", "passed": true,\n' +
        '      "detail": "four-layer answer key (root_cause_entities/types + raw_ground_truth)" } ] } }',
    },
    {
      title: 'Render a report',
      why: 'A self-contained HTML page: coverage, entity graph with a reference-integrity verdict, gates and score. All user-controlled strings are escaped.',
      cmd: 'node packages/cli/dist/main.js report --input examples/order-prod/bundle.json --target rca100 --output report.html',
      out: '<h2>Observability coverage</h2>\n<h2>Entity graph</h2>\n<h2>Quality gates</h2>\n<h2>Score</h2>',
    },
    {
      title: 'Self-evolve under human review',
      why: 'The engine proposes; it never mutates production on its own. A candidate that regresses stays pending, and its affected cases are marked stale for re-run.',
      cmd: 'node packages/cli/dist/main.js evolve propose --input examples/order-prod/proposal-draft.json',
      out:
        '{ "id": "prop-001", "layer": "L1",\n' +
        '  "regression": { "baselineScore": 96, "candidateScore": 93, "passed": false },\n' +
        '  "baseVersion": "c9d3266", "status": "pending" }',
    },
  ];

  // ── downloadable example pack ──────────────────────────────────────
  var PACK_META_URL = 'assets/example-pack.json';

  /** Human-readable size for the download card. */
  function formatBytes(bytes) {
    if (bytes < 1024) return bytes + ' B';
    return (bytes / 1024).toFixed(1) + ' KB';
  }

  /**
   * Build the download card.
   *
   * The metadata is fetched rather than inlined so the committed archive stays
   * the single source of truth: the site can never advertise a digest the
   * artefact does not have. When the fetch fails (an offline copy, or a
   * file:// preview) the card degrades to a repository link rather than lying.
   */
  function renderPackCard() {
    var body = el('div', { class: 'small', text: 'Reading pack metadata…' });
    var card = el('div', { class: 'card', style: 'margin-bottom:16px' }, [
      el('h4', { style: 'margin:0 0 6px', text: 'Take the example with you' }),
      body,
    ]);

    window
      // `no-store` keeps the card honest after a redeploy: a cached digest for a
      // replaced archive would be worse than no digest at all.
      .fetch(PACK_META_URL, { cache: 'no-store' })
      .then(function (response) {
        if (!response.ok) throw new Error('HTTP ' + response.status);
        return response.json();
      })
      .then(function (meta) {
        body.innerHTML = '';
        body.appendChild(
          el('p', {
            text:
              'One reproducible archive: the telemetry, drafts and rules every command below runs against, plus run.sh and a SHA-256 manifest.',
          }),
        );
        body.appendChild(
          el('div', { style: 'display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:8px 0' }, [
            el('a', { class: 'btn primary', href: 'assets/' + meta.file, download: meta.file, text: 'Download ' + meta.file }),
            el('span', { class: 'badge', text: meta.fileCount + ' files' }),
            el('span', { class: 'badge', text: formatBytes(meta.bytes) + ' gzipped' }),
            el('span', { class: 'badge ok', text: 'byte-reproducible' }),
          ]),
        );
        body.appendChild(codeBlock('sha256 · ' + meta.file, meta.sha256, 'text'));
        body.appendChild(
          codeBlock(
            'verify after download',
            'shasum -a 256 ' +
              meta.file +
              '\n# expect ' +
              meta.sha256 +
              '\n\n# every file inside is listed in MANIFEST.json with its own digest\n' +
              'tar -xzf ' +
              meta.file +
              '\ncd rca-bench-factory-examples && cat MANIFEST.json',
            'bash',
          ),
        );
        body.appendChild(
          el('p', {
            class: 'small',
            text: 'Rebuilding it from the same inputs produces identical bytes: the tar mtime, uid and gid are pinned to zero.',
          }),
        );
      })
      .catch(function () {
        body.innerHTML = '';
        body.appendChild(
          el('p', {
            text: 'Pack metadata could not be loaded here. The example files live in the repository, and the same eight commands are documented in docs/user-guide.md.',
          }),
        );
        body.appendChild(
          el('a', {
            class: 'btn',
            href: 'https://github.com/AgentiX-E/rca-bench-factory/tree/master/examples/order-prod',
            text: 'Browse examples/order-prod on GitHub',
          }),
        );
      });

    return card;
  }

  var PROGRESS_KEY = 'rbf-tutorial-progress';

  function loadProgress() {
    try {
      return JSON.parse(localStorage.getItem(PROGRESS_KEY) || '{}');
    } catch (e) {
      return {};
    }
  }

  function renderTutorial() {
    var view = document.getElementById('view');
    view.innerHTML = '';
    var progress = loadProgress();

    view.appendChild(
      sectionTitle('Tutorial', 'Eight steps from a raw export to a scored, reviewable benchmark. Tick a step to track your progress locally.'),
    );

    var bar = el('div', { class: 'progress' }, [el('div')]);
    view.appendChild(bar);

    view.appendChild(renderPackCard());

    var list = el('div', {});
    TUTORIAL.forEach(function (step, i) {
      var key = 'step-' + i;
      var done = !!progress[key];
      var node = el('div', { class: 'step card' + (done ? ' done' : ''), style: 'margin-bottom:12px' }, [
        el('div', {
          class: 'check',
          text: done ? '✓' : String(i + 1),
          onclick: function () {
            var p = loadProgress();
            if (p[key]) delete p[key];
            else p[key] = true;
            localStorage.setItem(PROGRESS_KEY, JSON.stringify(p));
            renderTutorial();
          },
        }),
        el('div', { style: 'flex:1' }, [
          el('h4', { style: 'margin:0 0 4px', text: step.title }),
          el('p', { text: step.why }),
          codeBlock('command', step.cmd, 'bash'),
          codeBlock('output', step.out, 'text'),
        ]),
      ]);
      list.appendChild(node);
    });
    view.appendChild(list);

    var doneCount = Object.keys(progress).filter(function (k) {
      return progress[k];
    }).length;
    bar.firstChild.style.width = Math.round((doneCount / TUTORIAL.length) * 100) + '%';
  }

  // ── score ───────────────────────────────────────────────────────────
  function renderScore() {
    var view = document.getElementById('view');
    view.innerHTML = '';
    view.appendChild(
      sectionTitle('Scoring', 'Compliance is a number, not an opinion: the mean of the structural pass rate and the Golden-Master checksum match rate.'),
    );

    var readout = el('div', { class: 'stat', style: 'margin-bottom:14px' }, [el('b', { text: '100' }), el('span', { text: 'score (0–100)' })]);
    var struct = el('input', { type: 'range', min: '0', max: '100', value: '100' });
    var sum = el('input', { type: 'range', min: '0', max: '100', value: '100' });

    function update() {
      var s = Number(struct.value) / 100;
      var c = Number(sum.value) / 100;
      var score = Math.round(((s + c) / 2) * 100);
      readout.firstChild.textContent = String(score);
    }
    struct.addEventListener('input', update);
    sum.addEventListener('input', update);

    view.appendChild(
      el('div', { class: 'card' }, [
        el('div', { style: 'display:flex;gap:20px;flex-wrap:wrap' }, [readout]),
        el('div', { style: 'margin-top:10px' }, [
          el('label', { class: 'small', text: 'structural pass rate' }),
          struct,
        ]),
        el('div', { style: 'margin-top:6px' }, [
          el('label', { class: 'small', text: 'checksum match rate (Golden Master anchors)' }),
          sum,
        ]),
        el('p', { class: 'small', text: 'Without --anchors the score is the structural pass rate alone; with anchors it is the mean of both.' }),
      ]),
    );

    view.appendChild(
      el('section', { class: 'block' }, [
        el('h3', { text: 'Live results for the demo bundle' }),
        el('div', { class: 'table-wrap' }, [
          el('table', {}, [
            el('thead', {}, [
              el('tr', {}, [el('th', { text: 'Target' }), el('th', { text: 'Score' }), el('th', { text: 'Checks passed' }), el('th', { text: 'Files' }), el('th', { text: 'Skipped' })]),
            ]),
            el('tbody', {}, Object.keys(TARGETS).map(function (id) {
              var t = TARGETS[id];
              var passed = t.report.structure.checks.filter(function (c) {
                return c.passed;
              }).length;
              return el('tr', {}, [
                el('td', { class: 'mono', text: id }),
                el('td', { text: String(t.report.score) }),
                el('td', { text: passed + ' / ' + t.report.structure.checks.length }),
                el('td', { text: String(Object.keys(t.files).length) }),
                el('td', { text: String(t.skipped.length) }),
              ]);
            })),
          ]),
        ]),
      ]),
    );
  }

  // ── faq ─────────────────────────────────────────────────────────────
  var FAQ = [
    ['Do I need OpenTelemetry?', 'No. OTel is the fastest path (T1), not a prerequisite. Flat files (T3) and LLM-assisted custom formats (T6) are first-class: the LLM proposes deterministic rules, the engine executes them, and the gates verify the result.'],
    ['Is the LLM required?', 'No. The deterministic core - ingest, transform, gates, export, score - never calls a model. The LLM is used only for rule generation and historical fault extraction, both routed through the H2 / H3 human checkpoints.'],
    ['Why is the RCA100 output JSON and not Parquet?', 'The official corpus serialises its modality tables as Parquet. The factory preserves the identical field contract as JSON so the output stays diffable and byte-stable for Golden-Master verification. Converting to Parquet is a downstream formatting step.'],
    ['What is deliberately out of scope?', 'Bulk day-based telemetry (AIOps2025 Parquet), live Kubernetes snapshots (Cloud-OpsBench tool cache, ITBench-Lite) and expert trajectory annotation. Those cannot be derived from a static per-case IR, and inventing them would be fabrication.'],
    ['Does it inject faults?', 'No. Chaos injection is out of scope; the factory converts telemetry you already have - including historical incidents - into benchmark contracts.'],
    ['Is OpenRCA 2.0 byte-compatible with the official release?', 'No, and that is stated openly: the official OpenRCA 2.0 evaluation framework and scorer are not open-sourced. The exporter emits a PAVE-semantic annotation contract that follows the published protocol description.'],
    ['How do you stop the answer key leaking into the task?', 'G5 and the answer-key-isolated check reject a task text containing the root-cause component, reason or occurrence tokens. The phrase "find the root cause" is legitimate and does not trip it.'],
  ];

  function renderFaq() {
    var view = document.getElementById('view');
    view.innerHTML = '';
    view.appendChild(sectionTitle('FAQ and boundaries', 'What the factory does, and - just as importantly - what it refuses to fake.'));
    var grid = el('div', { class: 'grid cols-2' });
    FAQ.forEach(function (entry) {
      grid.appendChild(el('div', { class: 'card' }, [el('h4', { text: entry[0] }), el('p', { text: entry[1] })]));
    });
    view.appendChild(grid);
  }

  // ── router ──────────────────────────────────────────────────────────
  var ROUTES = {
    '': renderOverview,
    overview: renderOverview,
    formats: renderFormats,
    gates: renderGates,
    tutorial: renderTutorial,
    score: renderScore,
    faq: renderFaq,
  };

  function currentRoute() {
    var hash = location.hash.replace(/^#\/?/, '');
    var parts = hash.split('/');
    return { name: parts[0] || 'overview', param: parts[1] || null };
  }

  function applyRoute() {
    var route = currentRoute();
    var render = ROUTES[route.name] || renderOverview;
    if (route.name === 'formats' && route.param) {
      var match = FORMATS.filter(function (f) {
        return f.id === route.param;
      })[0];
      if (match) state.format = match.id;
    }
    render();
    Array.prototype.forEach.call(document.querySelectorAll('nav.main a'), function (a) {
      a.classList.toggle('active', a.getAttribute('href') === '#/' + route.name);
    });
    window.scrollTo(0, 0);
  }

  // ── theme ───────────────────────────────────────────────────────────
  function initTheme() {
    var stored = null;
    try {
      stored = localStorage.getItem('rbf-theme');
    } catch (e) {
      stored = null;
    }
    var prefersLight = window.matchMedia && window.matchMedia('(prefers-color-scheme: light)').matches;
    var theme = stored || (prefersLight ? 'light' : 'dark');
    document.documentElement.setAttribute('data-theme', theme);
    var button = document.getElementById('theme-toggle');
    button.textContent = theme === 'light' ? 'dark mode' : 'light mode';
    button.addEventListener('click', function () {
      var next = document.documentElement.getAttribute('data-theme') === 'light' ? 'dark' : 'light';
      document.documentElement.setAttribute('data-theme', next);
      button.textContent = next === 'light' ? 'dark mode' : 'light mode';
      try {
        localStorage.setItem('rbf-theme', next);
      } catch (e) {
        /* storage unavailable - theme still applies for this session */
      }
    });
  }

  window.addEventListener('hashchange', applyRoute);
  document.addEventListener('DOMContentLoaded', function () {
    initTheme();
    applyRoute();
  });
})();
